export default "/* extracted from production bundle */\n:host {\n  display: block;\n  position: relative;\n}\n:host media-image img {\n  width: 100%;\n  height: 100%;\n}\nno-results-message {\n  margin: 30px 0;\n}\n.auto-height-grid {\n  grid-gap: 20px;\n  grid-template-columns: repeat(auto-fill, minmax(195px, 1fr));\n}\n@media only screen and (max-width: 740px) {\n  .auto-height-grid {\n    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));\n  }\n}\n@media only screen and (max-width: 768px) {\n  .auto-height-grid .title {\n    font-size: 1.5rem;\n  }\n}\n.auto-height-grid .grid-item {\n  padding-top: 150%;\n}\n.grid-item:hover .grid-content {\n  box-shadow: 0 3px 5px -1px #0003, 0 6px 10px #00000024, 0 1px 18px #0000001f;\n}\n.grid-content {\n  border: none;\n  box-shadow: 0 2px 1px -1px #0003, 0 1px 1px #00000024, 0 1px 3px #0000001f;\n  transition: box-shadow 0.2s ease-in-out;\n}\n.grid-label {\n  white-space: normal;\n  margin: 12px auto 0;\n  text-align: center;\n}\n.title {\n  color: var(--be-text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-weight: 500;\n  font-size: 1.8rem;\n}\n.title:hover {\n  color: var(--be-accent-default);\n}\n.subtitle {\n  display: flex;\n  justify-content: center;\n  font-size: 1.3rem;\n  margin: 8px 0;\n}\n.skeleton-grid {\n  position: relative !important;\n  left: 0;\n  right: 0;\n}\nskeleton.title {\n  height: 2.8rem;\n}\nskeleton.subtitle {\n  height: 1.3rem;\n}";